#!/usr/bin/env python3
"""
config_watch.py — periodically scan system configuration files for modifications.

- Computes SHA-256 hashes for watched paths (files and/or directories).
- Stores state in a JSON file so changes persist across restarts.
- Reports: added/removed/modified, plus basic metadata (mode/uid/gid/mtime/size).
- Optionally prints a unified diff for text files when modified.

Examples:
  sudo python3 config_watch.py --interval 300 --paths /etc --paths /usr/local/etc
  sudo python3 config_watch.py --paths /etc/ssh/sshd_config /etc/fstab --diff
  sudo python3 config_watch.py --config ./watch.json --state ./state.json
"""

from __future__ import annotations

import argparse
import difflib
import fnmatch
import hashlib
import json
import os
import signal
import stat as statmod
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple


DEFAULT_IGNORES = [
    # common ephemeral / generated files under /etc
    "*/.git/*",
    "*/.svn/*",
    "*/.hg/*",
    "*/shadow-*",
    "*/gshadow-*",
    "*/passwd-*",
    "*/group-*",
    "*/subuid-*",
    "*/subgid-*",
    "*/ld.so.cache",
    "*/mtab",
    "*/resolv.conf",  # often managed by resolvers / DHCP
    "*/hostname",     # sometimes managed automatically
]


@dataclass(frozen=True)
class FileRecord:
    path: str
    sha256: str
    size: int
    mtime_ns: int
    mode: int
    uid: int
    gid: int

    def to_dict(self) -> dict:
        return {
            "path": self.path,
            "sha256": self.sha256,
            "size": self.size,
            "mtime_ns": self.mtime_ns,
            "mode": self.mode,
            "uid": self.uid,
            "gid": self.gid,
        }

    @staticmethod
    def from_dict(d: dict) -> "FileRecord":
        return FileRecord(
            path=d["path"],
            sha256=d["sha256"],
            size=int(d["size"]),
            mtime_ns=int(d["mtime_ns"]),
            mode=int(d["mode"]),
            uid=int(d["uid"]),
            gid=int(d["gid"]),
        )


def sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            b = f.read(chunk_size)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def is_probably_text(path: Path, sample_size: int = 4096) -> bool:
    try:
        data = path.read_bytes()[:sample_size]
    except Exception:
        return False
    if not data:
        return True
    # Heuristic: if it contains NUL, treat as binary
    if b"\x00" in data:
        return False
    # If mostly printable / whitespace, treat as text
    printable = sum(1 for c in data if 32 <= c <= 126 or c in (9, 10, 13))
    return printable / len(data) > 0.85


def read_text_lines(path: Path, max_bytes: int = 512 * 1024) -> Optional[List[str]]:
    try:
        b = path.read_bytes()
        if len(b) > max_bytes:
            return None
        # decode with replacement to avoid crashes on odd encodings
        s = b.decode("utf-8", errors="replace")
        return s.splitlines(keepends=True)
    except Exception:
        return None


def matches_any(path_str: str, patterns: List[str]) -> bool:
    for pat in patterns:
        if fnmatch.fnmatch(path_str, pat):
            return True
    return False


def iter_files(paths: List[Path], ignores: List[str], follow_symlinks: bool) -> Iterable[Path]:
    for root in paths:
        try:
            root = root.resolve(strict=False)
        except Exception:
            pass

        if root.is_file():
            p = root
            p_str = str(p)
            if not matches_any(p_str, ignores):
                yield p
            continue

        if root.is_dir():
            for dirpath, dirnames, filenames in os.walk(root, followlinks=follow_symlinks):
                # skip ignored directories early
                dirpath_str = str(Path(dirpath))
                # prune subdirs that are ignored by pattern
                pruned = []
                for d in dirnames:
                    full = str(Path(dirpath) / d)
                    if matches_any(full, ignores):
                        pruned.append(d)
                for d in pruned:
                    dirnames.remove(d)

                for name in filenames:
                    p = Path(dirpath) / name
                    p_str = str(p)
                    if matches_any(p_str, ignores):
                        continue
                    yield p
            continue

        # Non-existent or special path: ignore here; it will be surfaced as "missing" via state diffs.


def snapshot(paths: List[Path], ignores: List[str], follow_symlinks: bool) -> Dict[str, FileRecord]:
    records: Dict[str, FileRecord] = {}
    for p in iter_files(paths, ignores, follow_symlinks):
        try:
            st = p.stat() if follow_symlinks else p.lstat()
        except FileNotFoundError:
            continue
        except PermissionError:
            continue

        # only regular files
        if not statmod.S_ISREG(st.st_mode):
            continue

        try:
            digest = sha256_file(p)
        except (PermissionError, FileNotFoundError, OSError):
            continue

        rec = FileRecord(
            path=str(p),
            sha256=digest,
            size=int(st.st_size),
            mtime_ns=int(getattr(st, "st_mtime_ns", int(st.st_mtime * 1e9))),
            mode=int(st.st_mode),
            uid=int(st.st_uid),
            gid=int(st.st_gid),
        )
        records[rec.path] = rec
    return records


def load_state(state_path: Path) -> Dict[str, FileRecord]:
    if not state_path.exists():
        return {}
    data = json.loads(state_path.read_text(encoding="utf-8"))
    recs = {}
    for p, d in data.get("files", {}).items():
        recs[p] = FileRecord.from_dict(d)
    return recs


def save_state(state_path: Path, records: Dict[str, FileRecord]) -> None:
    state_path.parent.mkdir(parents=True, exist_ok=True)
    data = {
        "version": 1,
        "generated_at": int(time.time()),
        "files": {p: r.to_dict() for p, r in sorted(records.items())},
    }
    tmp = state_path.with_suffix(state_path.suffix + ".tmp")
    tmp.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")
    tmp.replace(state_path)


def diff_records(old: Dict[str, FileRecord], new: Dict[str, FileRecord]) -> Tuple[List[str], List[str], List[str]]:
    old_keys = set(old.keys())
    new_keys = set(new.keys())
    added = sorted(new_keys - old_keys)
    removed = sorted(old_keys - new_keys)
    modified = sorted([k for k in (old_keys & new_keys) if old[k].sha256 != new[k].sha256 or old[k].mode != new[k].mode
                       or old[k].uid != new[k].uid or old[k].gid != new[k].gid])
    return added, removed, modified


def fmt_mode(mode: int) -> str:
    return oct(mode & 0o7777)


def print_event(added: List[str], removed: List[str], modified: List[str],
                old: Dict[str, FileRecord], new: Dict[str, FileRecord],
                show_diff: bool) -> None:
    ts = time.strftime("%Y-%m-%d %H:%M:%S %z")
    if not (added or removed or modified):
        print(f"[{ts}] no changes")
        return

    print(f"[{ts}] CHANGES DETECTED")
    for p in added:
        r = new[p]
        print(f"  + {p} sha256={r.sha256[:12]} size={r.size} mode={fmt_mode(r.mode)} uid={r.uid} gid={r.gid}")
    for p in removed:
        r = old[p]
        print(f"  - {p} (was sha256={r.sha256[:12]} size={r.size} mode={fmt_mode(r.mode)} uid={r.uid} gid={r.gid})")
    for p in modified:
        o, n = old[p], new[p]
        print(f"  * {p}")
        if o.sha256 != n.sha256:
            print(f"      sha256: {o.sha256[:12]} -> {n.sha256[:12]}")
        if o.size != n.size:
            print(f"      size:   {o.size} -> {n.size}")
        if o.mtime_ns != n.mtime_ns:
            print(f"      mtime:  {o.mtime_ns} -> {n.mtime_ns}")
        if o.mode != n.mode:
            print(f"      mode:   {fmt_mode(o.mode)} -> {fmt_mode(n.mode)}")
        if o.uid != n.uid:
            print(f"      uid:    {o.uid} -> {n.uid}")
        if o.gid != n.gid:
            print(f"      gid:    {o.gid} -> {n.gid}")

        if show_diff:
            path = Path(p)
            if path.exists() and path.is_file() and is_probably_text(path):
                old_lines = read_text_lines(path)  # note: current file; we don't have old content
                # Without old content stored, we can't show true "before" diff.
                # We can at least show a context-less note.
                if old_lines is not None:
                    print("      diff: (not available without storing previous contents)")
                else:
                    print("      diff: skipped (file too large or unreadable)")


_stop = False
def _handle_sig(sig, frame):
    global _stop
    _stop = True


def load_config(path: Optional[Path]) -> dict:
    if not path:
        return {}
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError("config must be a JSON object")
    return data


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--paths", action="append", default=[],
                    help="Path to watch (file or directory). Can be repeated.")
    ap.add_argument("--interval", type=int, default=300, help="Seconds between scans (default: 300).")
    ap.add_argument("--state", default="./config_watch_state.json", help="State file path (default: ./config_watch_state.json).")
    ap.add_argument("--config", default=None, help="Optional JSON config file (merges into CLI).")
    ap.add_argument("--ignore", action="append", default=[], help="Glob pattern to ignore. Can be repeated.")
    ap.add_argument("--follow-symlinks", action="store_true", help="Follow symlinks when walking directories.")
    ap.add_argument("--one-shot", action="store_true", help="Scan once and exit (writes state).")
    ap.add_argument("--diff", action="store_true", help="(Limited) attempt to show diffs; requires storing old content (not implemented).")
    args = ap.parse_args()

    cfg = load_config(Path(args.config)) if args.config else {}
    paths = [Path(p) for p in (args.paths or cfg.get("paths") or ["/etc"])]
    interval = int(cfg.get("interval", args.interval))
    state_path = Path(cfg.get("state", args.state))
    ignores = list(DEFAULT_IGNORES)
    ignores.extend(cfg.get("ignore", []))
    ignores.extend(args.ignore or [])
    follow = bool(cfg.get("follow_symlinks", args.follow_symlinks))
    one_shot = bool(cfg.get("one_shot", args.one_shot))
    show_diff = bool(cfg.get("diff", args.diff))

    signal.signal(signal.SIGINT, _handle_sig)
    signal.signal(signal.SIGTERM, _handle_sig)

    old = load_state(state_path)

    while True:
        new = snapshot(paths, ignores, follow)
        added, removed, modified = diff_records(old, new)

        print_event(added, removed, modified, old, new, show_diff)
        save_state(state_path, new)
        old = new

        if one_shot or _stop:
            break
        time.sleep(max(1, interval))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
